// SetField sets the value of a field with the given name. It returns an error if
// the field is not defined in the schema, or if the type mismatched the field
// type.
//
// A sql.Querier that is not of the field's type is handed to SetFieldExpr, so
// that what Field returns for a field can be set back on it.
func (m *Mutation) SetField(name string, value ent.Value) error {
	switch name {
	case FieldMor:
		v, ok := value.(string)
		if !ok {
			if e, ok := value.(sql.Querier); ok {
				return m.SetFieldExpr(name, e)
			}
			return fmt.Errorf("unexpected type %T for field %s", value, name)
		}
		m.SetMor(v)
		return nil
	case FieldMorEvent:
		v, ok := value.(string)
		if !ok {
			if e, ok := value.(sql.Querier); ok {
				return m.SetFieldExpr(name, e)
			}
			return fmt.Errorf("unexpected type %T for field %s", value, name)
		}
		m.SetMorEvent(v)
		return nil
	case FieldType:
		v, ok := value.(string)
		if !ok {
			if e, ok := value.(sql.Querier); ok {
				return m.SetFieldExpr(name, e)
			}
			return fmt.Errorf("unexpected type %T for field %s", value, name)
		}
		m.SetType(v)
		return nil
	case FieldKind:
		v, ok := value.(int32)
		if !ok {
			if e, ok := value.(sql.Querier); ok {
				return m.SetFieldExpr(name, e)
			}
			return fmt.Errorf("unexpected type %T for field %s", value, name)
		}
		m.SetKind(v)
		return nil
	case FieldVia:
		v, ok := value.(int32)
		if !ok {
			if e, ok := value.(sql.Querier); ok {
				return m.SetFieldExpr(name, e)
			}
			return fmt.Errorf("unexpected type %T for field %s", value, name)
		}
		m.SetVia(v)
		return nil
	case FieldMorTransaction:
		v, ok := value.(string)
		if !ok {
			if e, ok := value.(sql.Querier); ok {
				return m.SetFieldExpr(name, e)
			}
			return fmt.Errorf("unexpected type %T for field %s", value, name)
		}
		m.SetMorTransaction(v)
		return nil
	case FieldMorSubscription:
		v, ok := value.(string)
		if !ok {
			if e, ok := value.(sql.Querier); ok {
				return m.SetFieldExpr(name, e)
			}
			return fmt.Errorf("unexpected type %T for field %s", value, name)
		}
		m.SetMorSubscription(v)
		return nil
	case FieldMorAdjustment:
		v, ok := value.(string)
		if !ok {
			if e, ok := value.(sql.Querier); ok {
				return m.SetFieldExpr(name, e)
			}
			return fmt.Errorf("unexpected type %T for field %s", value, name)
		}
		m.SetMorAdjustment(v)
		return nil
	case FieldDateOccurred:
		v, ok := value.(time.Time)
		if !ok {
			if e, ok := value.(sql.Querier); ok {
				return m.SetFieldExpr(name, e)
			}
			return fmt.Errorf("unexpected type %T for field %s", value, name)
		}
		m.SetDateOccurred(v)
		return nil
	case FieldTransaction:
		v, ok := value.(*levyan.NoticeTransaction)
		if !ok {
			if e, ok := value.(sql.Querier); ok {
				return m.SetFieldExpr(name, e)
			}
			return fmt.Errorf("unexpected type %T for field %s", value, name)
		}
		m.SetTransaction(v)
		return nil
	case FieldOutcome:
		v, ok := value.(int32)
		if !ok {
			if e, ok := value.(sql.Querier); ok {
				return m.SetFieldExpr(name, e)
			}
			return fmt.Errorf("unexpected type %T for field %s", value, name)
		}
		m.SetOutcome(v)
		return nil
	case FieldTries:
		v, ok := value.(int32)
		if !ok {
			if e, ok := value.(sql.Querier); ok {
				return m.SetFieldExpr(name, e)
			}
			return fmt.Errorf("unexpected type %T for field %s", value, name)
		}
		m.SetTries(v)
		return nil
	case FieldError:
		v, ok := value.(string)
		if !ok {
			if e, ok := value.(sql.Querier); ok {
				return m.SetFieldExpr(name, e)
			}
			return fmt.Errorf("unexpected type %T for field %s", value, name)
		}
		m.SetError(v)
		return nil
	case FieldDateRetry:
		v, ok := value.(time.Time)
		if !ok {
			if e, ok := value.(sql.Querier); ok {
				return m.SetFieldExpr(name, e)
			}
			return fmt.Errorf("unexpected type %T for field %s", value, name)
		}
		m.SetDateRetry(v)
		return nil
	case FieldDateDone:
		v, ok := value.(time.Time)
		if !ok {
			if e, ok := value.(sql.Querier); ok {
				return m.SetFieldExpr(name, e)
			}
			return fmt.Errorf("unexpected type %T for field %s", value, name)
		}
		m.SetDateDone(v)
		return nil
	case FieldDateCreated:
		v, ok := value.(time.Time)
		if !ok {
			if e, ok := value.(sql.Querier); ok {
				return m.SetFieldExpr(name, e)
			}
			return fmt.Errorf("unexpected type %T for field %s", value, name)
		}
		m.SetDateCreated(v)
		return nil
	case FieldBillingAccountId:
		v, ok := value.(uuid.UUID)
		if !ok {
			if e, ok := value.(sql.Querier); ok {
				return m.SetFieldExpr(name, e)
			}
			return fmt.Errorf("unexpected type %T for field %s", value, name)
		}
		m.SetBillingAccountId(v)
		return nil
	case FieldSubscriptionId:
		v, ok := value.(uuid.UUID)
		if !ok {
			if e, ok := value.(sql.Querier); ok {
				return m.SetFieldExpr(name, e)
			}
			return fmt.Errorf("unexpected type %T for field %s", value, name)
		}
		m.SetSubscriptionId(v)
		return nil
	case FieldCheckoutId:
		v, ok := value.(uuid.UUID)
		if !ok {
			if e, ok := value.(sql.Querier); ok {
				return m.SetFieldExpr(name, e)
			}
			return fmt.Errorf("unexpected type %T for field %s", value, name)
		}
		m.SetCheckoutId(v)
		return nil
	}
	return fmt.Errorf("unknown Notice field %s", name)
}

// SetFieldExpr assigns the field with the given name a SQL expression, which
// the database evaluates as the UPDATE writes the row. It replaces any value
// the field was set, added, appended or cleared with, as setting it again
// would, and so the column is assigned once.
//
// The field is listed by Fields and Field returns the expression, so a hook
// sees it as it sees any other. What it does not have is a value: a field
// with a validator is refused, since there is nothing for the validator to
// check, and so is one that only a create could write. A create refuses a
// mutation holding an expression at all.
func (m *Mutation) SetFieldExpr(name string, expr sql.Querier) error {
	if expr == nil {
		return fmt.Errorf("no expression for field %s", name)
	}
	if m.op.Is(ent.OpCreate) {
		return fmt.Errorf("field %s cannot be assigned an expression: a create writes values, and an expression is written only by an update", name)
	}
	switch name {
	case FieldMor:
		return fmt.Errorf("field %s cannot be assigned an expression: it is immutable, and an expression is written only by an update", name)
	case FieldMorEvent:
		return fmt.Errorf("field %s cannot be assigned an expression: it is immutable, and an expression is written only by an update", name)
	case FieldType:
		return fmt.Errorf("field %s cannot be assigned an expression: it is immutable, and an expression is written only by an update", name)
	case FieldKind:
		return fmt.Errorf("field %s cannot be assigned an expression: it is immutable, and an expression is written only by an update", name)
	case FieldVia:
		return fmt.Errorf("field %s cannot be assigned an expression: it is immutable, and an expression is written only by an update", name)
	case FieldMorTransaction:
		return fmt.Errorf("field %s cannot be assigned an expression: it is immutable, and an expression is written only by an update", name)
	case FieldMorSubscription:
		return fmt.Errorf("field %s cannot be assigned an expression: it is immutable, and an expression is written only by an update", name)
	case FieldMorAdjustment:
		return fmt.Errorf("field %s cannot be assigned an expression: it is immutable, and an expression is written only by an update", name)
	case FieldDateOccurred:
		return fmt.Errorf("field %s cannot be assigned an expression: it is immutable, and an expression is written only by an update", name)
	case FieldTransaction:
		m.ResetTransaction()
	case FieldOutcome:
		m.ResetOutcome()
	case FieldTries:
		m.ResetTries()
	case FieldError:
		m.ResetError()
	case FieldDateRetry:
		m.ResetDateRetry()
	case FieldDateDone:
		m.ResetDateDone()
	case FieldDateCreated:
		return fmt.Errorf("field %s cannot be assigned an expression: it is immutable, and an expression is written only by an update", name)
	case FieldBillingAccountId:
		return fmt.Errorf("field %s cannot be assigned an expression: it holds an edge, which is set through the edge", name)
	case FieldSubscriptionId:
		return fmt.Errorf("field %s cannot be assigned an expression: it holds an edge, which is set through the edge", name)
	case FieldCheckoutId:
		return fmt.Errorf("field %s cannot be assigned an expression: it holds an edge, which is set through the edge", name)
	default:
		return fmt.Errorf("unknown Notice field %s", name)
	}
	if m.exprs == nil {
		m.exprs = make(map[string]sql.Querier)
	}
	m.exprs[name] = expr
	return nil
}

// FieldExpr returns the expression the field with the given name was assigned
// by SetFieldExpr. The second return value reports whether it was.
func (m *Mutation) FieldExpr(name string) (sql.Querier, bool) {
	e, ok := m.exprs[name]
	return e, ok
}

// ExprFields returns the fields that were assigned an expression by
// SetFieldExpr.
func (m *Mutation) ExprFields() []string {
	var fields []string
	if _, ok := m.exprs[FieldTransaction]; ok {
		fields = append(fields, FieldTransaction)
	}
	if _, ok := m.exprs[FieldOutcome]; ok {
		fields = append(fields, FieldOutcome)
	}
	if _, ok := m.exprs[FieldTries]; ok {
		fields = append(fields, FieldTries)
	}
	if _, ok := m.exprs[FieldError]; ok {
		fields = append(fields, FieldError)
	}
	if _, ok := m.exprs[FieldDateRetry]; ok {
		fields = append(fields, FieldDateRetry)
	}
	if _, ok := m.exprs[FieldDateDone]; ok {
		fields = append(fields, FieldDateDone)
	}
	return fields
}

// AddedFields returns all numeric fields that were incremented/decremented during
// this mutation.
func (m *Mutation) AddedFields() []string {
	var fields []string
	if m.addkind != nil {
		fields = append(fields, FieldKind)
	}
	if m.addvia != nil {
		fields = append(fields, FieldVia)
	}
	if m.addoutcome != nil {
		fields = append(fields, FieldOutcome)
	}
	if m.addtries != nil {
		fields = append(fields, FieldTries)
	}
	return fields
}

// AddedField returns the numeric value that was incremented/decremented on a field
// with the given name. The second boolean return value indicates that this field
// was not set, or was not defined in the schema.
func (m *Mutation) AddedField(name string) (ent.Value, bool) {
	switch name {
	case FieldKind:
		return m.AddedKind()
	case FieldVia:
		return m.AddedVia()
	case FieldOutcome:
		return m.AddedOutcome()
	case FieldTries:
		return m.AddedTries()
	}
	return nil, false
}

// AddField adds the value to the field with the given name. It returns an error if
// the field is not defined in the schema, or if the type mismatched the field
// type.
func (m *Mutation) AddField(name string, value ent.Value) error {
	switch name {
	case FieldKind:
		v, ok := value.(int32)
		if !ok {
			return fmt.Errorf("unexpected type %T for field %s", value, name)
		}
		m.AddKind(v)
		return nil
	case FieldVia:
		v, ok := value.(int32)
		if !ok {
			return fmt.Errorf("unexpected type %T for field %s", value, name)
		}
		m.AddVia(v)
		return nil
	case FieldOutcome:
		v, ok := value.(int32)
		if !ok {
			return fmt.Errorf("unexpected type %T for field %s", value, name)
		}
		m.AddOutcome(v)
		return nil
	case FieldTries:
		v, ok := value.(int32)
		if !ok {
			return fmt.Errorf("unexpected type %T for field %s", value, name)
		}
		m.AddTries(v)
		return nil
	}
	return fmt.Errorf("unknown Notice numeric field %s", name)
}

// ClearedFields returns all nullable fields that were cleared during this
// mutation.
func (m *Mutation) ClearedFields() []string {
	var fields []string
	if m.FieldCleared(FieldDateOccurred) {
		fields = append(fields, FieldDateOccurred)
	}
	if m.FieldCleared(FieldTransaction) {
		fields = append(fields, FieldTransaction)
	}
	if m.FieldCleared(FieldDateRetry) {
		fields = append(fields, FieldDateRetry)
	}
	if m.FieldCleared(FieldDateDone) {
		fields = append(fields, FieldDateDone)
	}
	if m.FieldCleared(FieldDateCreated) {
		fields = append(fields, FieldDateCreated)
	}
	if m.FieldCleared(FieldBillingAccountId) {
		fields = append(fields, FieldBillingAccountId)
	}
	if m.FieldCleared(FieldSubscriptionId) {
		fields = append(fields, FieldSubscriptionId)
	}
	if m.FieldCleared(FieldCheckoutId) {
		fields = append(fields, FieldCheckoutId)
	}
	return fields
}

// FieldCleared returns a boolean indicating if a field with the given name was
// cleared in this mutation.
func (m *Mutation) FieldCleared(name string) bool {
	_, ok := m.clearedFields[name]
	return ok
}

// ClearField clears the value of the field with the given name. It returns an
