// AddedEdges returns all edge names that were set/added in this mutation.
func (m *Mutation) AddedEdges() []string {
	edges := make([]string, 0, 3)
	if m.billing_account != nil {
		edges = append(edges, EdgeBillingAccount)
	}
	if m.subscription != nil {
		edges = append(edges, EdgeSubscription)
	}
	if m.checkout != nil {
		edges = append(edges, EdgeCheckout)
	}
	return edges
}

// AddedIds returns all Ids (to other nodes) that were added for the given edge
// name in this mutation.
func (m *Mutation) AddedIds(name string) []ent.Value {
	switch name {
	case EdgeBillingAccount:
		if id := m.billing_account; id != nil {
			return []ent.Value{*id}
		}
	case EdgeSubscription:
		if id := m.subscription; id != nil {
			return []ent.Value{*id}
		}
	case EdgeCheckout:
		if id := m.checkout; id != nil {
			return []ent.Value{*id}
		}
	}
	return nil
}

